 $('showMedia').checked=state.showMedia;$('videoWeave').checked=!!state.videoWeave;$('gradeMedia').checked=state.gradeMedia;$('mediaShape').value=state.mediaShape;$('reducedMotion').checked=state.reduced;$('materialMode').value=state.materialMode;$('debugView').value=state.debug;
