function drawWave(){const c=$('wave'),r=c.getBoundingClientRect();if(!r.width)return;c.width=Math.round(r.width*2);c.height=Math.round(r.height*2);const x=c.getContext('2d'),wave=C.decode(score.waveform),w=c.width,h=c.height;x.clearRect(0,0,w,h);const bars=Math.floor(w/4);for(let i=0;i<bars;i++){const v=wave[Math.floor(i/bars*wave.length)]/255;const bh=Math.max(2,v*h*.82);x.fillStyle=i/bars<currentTime/score.duration?'#9cae9b':'#344a56';x.fillRect(i*4,h/2-bh/2,2,bh);}let laneCount=Object.values(state.director.lanes).reduce((a,b)=>a+b.length,0);if(laneCount){x.fillStyle='#d3b983';for(const points of Object.values(state.director.lanes))for(const p of points){x.fillRect(p.time/score.duration*w,h-5,3,5);}}}
