 $('autoIndicator').style.color=n?'var(--gold)':'var(--teal)';$('recordBtn').classList.toggle('recording',state.director.recording);$('recordBtn').textContent=state.director.recording?'■ Finish take':'● Record gestures';
 $('returnTime').value=String(state.director.releaseDuration);$('resonantFloor').checked=state.flow.resonance;$('braidDetail').checked=state.flow.braid;$('edgePolish').checked=state.flow.edge;
 $('xyPad').setAttribute('aria-valuenow',d.values.density.toFixed(3));$('xyPad').setAttribute('aria-valuetext',`Density ${d.values.density.toFixed(2)}, intimacy ${d.values.intimacy.toFixed(2)}`);$('padDot').style.left=(d.values.density*100)+'%';$('padDot').style.top=((1-d.values.intimacy)*100)+'%';
